    "Your first interaction": "Ваше первое взаимодействие",
    "Every map starts with the starting room. Create it with the button on the left.": "Каждая карта начинается со стартовой комнаты. Создайте её кнопкой слева.",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "Выберите тайл на палитре и положите его на поле; нажмите R, чтобы повернуть его. Пока что поставьте два разных тайла: во время игры их достанут из коробки и разложат.",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "Кнопка «Герой» (H) задаёт стартовые клетки наших искателей приключений. Выберите от 2 до 4 клеток в стартовой комнате.",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "Чтобы открывать карту понемногу, нужно создать новую комнату. Она появляется, когда используется объект, если запрограммировать триггер, открывающий комнату. Попробуем: нажмите кнопку «Объект» (O) и выберите дверь. Затем добавьте триггер «Открыть комнату».",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "Вы создали своё первое взаимодействие с обстановкой. В игре герой откроет дверь, и на поле выйдут тайлы следующей комнаты. Теперь заполним эту комнату: поставьте в комнату сундук и запрограммируйте триггер, который даёт игрокам предметы (остальные кнопки и триггеры подождут).",
    "📂 Import a save of the game (.sav)": "📂 Импортировать сохранение игры (.sav)",
    "Clear all": "Очистить всё",
    "Search an item…": "Найти предмет…",
    "Only what the party has": "Только то, что есть у отряда",
    "skills": "навыки",
    "Others": "Прочее",
    "Clear the whole starting inventory?": "Очистить весь стартовый инвентарь?",
    "Replace the starting inventory with the one of this save?": "Заменить стартовый инвентарь инвентарём из этого сохранения?",
    "Imported from the save": "Импортировано из сохранения",
    "This file is not a save of the game.": "Этот файл не является сохранением игры.",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "Для отряда ветеранов: то, что у него уже есть в начале кампании, добытое в прежних битвах. Отряд получает это, когда начинается кампания. Предметы берутся из Мастерской (вкладки «Предметы» и «Оружие»), навыки — с вкладки «Навыки» (или игровые). Пулы предметов сгенерированных карт исключают уникальные предметы, которые у отряда уже есть, и игра никогда не выдаёт предмет дважды.",
    "Starting gold": "Стартовое золото",
