    "Placeholders: {vilao} {lugar} {alvo} {n} {X} {limite} {desde}… In Portuguese, “de {vilao}” becomes “do …” by itself.": "Подстановки: {vilao} {lugar} {alvo} {n} {X} {limite} {desde}… В португальском «de {vilao}» само превращается в «do …».",
