    "What it may change:": "Что может измениться:",
    "What stays:": "Что остаётся:",
    "the intensity of the rooms with monsters and of the triggers that call monsters from the pool, all by the same step (from −6 to +6, always within 1 to 10);": "интенсивность комнат с монстрами и триггеров, вызывающих монстров из пула, все на один и тот же шаг (от −6 до +6, всегда в пределах от 1 до 10);",
    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "ранги для 1–2, 3 и 4 героев у монстров, поставленных вручную, по правилу игры (как ⚖ Баланс у монстра).",
    "the campaign progression, the monster and item pools, the monsters themselves, the objects, the triggers and the texts.": "прогресс кампании, пулы монстров и предметов, сами монстры, объекты, триггеры и тексты.",
    "Work out the proposal": "Рассчитать предложение",
    "Simulating…": "Симуляция…",
    "No adjustment does better than the map as it is.": "Никакая настройка не лучше карты в нынешнем виде.",
