    "Add, remove or move?": "Добавить, убрать или переместить?",
    "Keep what stands on it (objects, monsters)": "Оставить то, что стоит на нём (объекты, монстры)",
    "Click the marker": "Щёлкните метку",
    "Marker (where it goes):": "Метка (куда перемещается):",
    "Click the object to move.": "Щёлкните объект, который нужно переместить.",
    "Click the tile to move (any room).": "Щёлкните тайл, который нужно переместить (любой комнаты).",
    "That one is a marker: click the object itself.": "Это метка: щёлкните сам объект.",
    "Click a tile (not its marker).": "Щёлкните тайл (не его метку).",
    "Click the object first.": "Сначала щёлкните объект.",
    "Click the tile first.": "Сначала щёлкните тайл.",
    "Click a second object, not the one that moves.": "Щёлкните второй объект, не тот, который перемещается.",
    "Click the marker: the same tile laid again, where it goes.": "Щёлкните метку: тот же тайл, положенный снова туда, куда он должен попасть.",
    "Click the marker tile.": "Щёлкните тайл-метку.",
    "marker": "метка",
    "Move the tile": "Переместить тайл",
    "Lays this one as the marker; then click the object whose use moves the tile.": "Кладёт этот тайл как метку; затем щёлкните объект, использование которого перемещает тайл.",
    "Remove only that tile, keeping objects and monsters": "Убрать только этот тайл, оставив объекты и монстров",
    "(keeps what stands on it)": "(оставляет то, что стоит на нём)",
    "\"{q}\": move tile without a tile": "«{Q}»: перемещение тайла без тайла",
    "\"{q}\": move tile without a marker": "«{Q}»: перемещение тайла без метки",
