    "\"{q}\": move an object without a marker": "«{Q}»: перемещение объекта без метки",
    "\"{q}\": remove tile keeping what stands on it, but the tile is not wholly over an underlay (warning)": "«{Q}»: удаление тайла с сохранением того, что на нём, но тайл лежит не целиком на подложке (предупреждение)",
    "Drag moves": "Перетаскивание двигает",
