    "Hero space {n}": "Клетка героя {n}",
    "Space {n}. Heroes start here ({n} to {n} spaces in the starting room).": "Клетка {n}. Здесь начинают герои (от {n} до {n} клеток в стартовой комнате).",
    ", or brought by a trigger when something happens.": ", или приведённые триггером, когда что-то происходит.",
    "Checklist": "Список проверки",
    "Click a piece to edit it": "Щёлкните деталь, чтобы изменить её",
    "Click the spaces where the heroes start (starting room only, {n} to {n}). (H)": "Щёлкните клетки, где начинают герои (только стартовая комната, от {n} до {n}). (H)",
    "Click what you want to remove. (D)": "Щёлкните то, что хотите убрать. (D)",
    "Create the starting room": "Создать стартовую комнату",
    "Create the starting room.": "Создайте стартовую комнату.",
    "Doors, chests, tokens… Any object can carry triggers and requirements. Staircases and bridges are floor: they may go off the tiles. (O)": "Двери, сундуки, жетоны… Любой объект может нести триггеры и требования. Лестницы и мосты считаются полом: они могут выходить за тайлы. (O)",
    "Edit": "Изменить",
    "Erase the rooms of this map (tiles, objects, monsters, hero spaces, triggers). The workshop, the map setup and the campaign stay. Asks first and offers to export.": "Стирает комнаты этой карты (тайлы, объекты, монстров, клетки героев, триггеры). Мастерская, настройка карты и кампания остаются. Сначала спрашивает и предлагает экспорт.",
    "Esc clears": "Esc снимает выбор",
    "Esc selects": "Esc выбирает",
    "Fit the map in view": "Вписать карту в экран",
    "Give each room its fight: monsters placed in it with": "Дайте каждой комнате свой бой: монстры, поставленные в неё инструментом",
    "Give the map a name first": "Сначала дайте карте название",
    "Give the map a name.": "Дайте карте название.",
    "Hints": "Подсказки",
    "Level": "Уровень",
    "Monsters placed in a room. In the starting room they are there from the start": "Монстры, поставленные в комнату. В стартовой комнате они есть с самого начала",
    "Monsters placed in a room. In the starting room they are there from the start; in any other room they enter automatically when the room opens. Monsters that come later (in a room already open) use a “{q}” trigger. (E)": "Монстры, поставленные в комнату. В стартовой комнате они есть с самого начала; в любой другой комнате они вступают в игру автоматически, когда комната открывается. Монстры, приходящие позже (в уже открытую комнату), используют триггер «{Q}». (E)",
    "Name of the map": "Название карты",
    "No room yet": "Комнат пока нет",
    "Paste the copied piece (Ctrl+V): click where it goes": "Вставьте скопированную деталь (Ctrl+V): щёлкните, куда её поставить",
    "Pick a tile in the palette and click the board. R rotates. Each physical tile (side A or B) only once per room; same-level tiles cannot overlap. Underlays go under the tiles. (T)": "Выберите тайл на палитре и щёлкните по полю. R поворачивает. Каждый физический тайл (сторона A или B) только один раз на комнату; тайлы одного уровня не могут перекрываться. Подложки кладутся под тайлы. (T)",
    "Pick the level of the elevated tile on the ribbon and click one of its sockets (the dots: between two squares on a straight edge, never a corner). The pillar belongs to that tile and enters the game with it. Level {n} tiles take short, medium or tall pillars": "Выберите на панели уровень возвышенного тайла и щёлкните одно из его гнёзд (точки: между двумя клетками на прямом краю, никогда в углу). Колонна принадлежит этому тайлу и попадает в игру вместе с ним. Тайлы уровня {n} принимают низкие, средние или высокие колонны",
    "Pick the level of the elevated tile on the ribbon and click one of its sockets (the dots: between two squares on a straight edge, never a corner). The pillar belongs to that tile and enters the game with it. Level {n} tiles take short, medium or tall pillars; level {n} medium or tall; level {n} tall. (P)": "Выберите на панели уровень возвышенного тайла и щёлкните одно из его гнёзд (точки: между двумя клетками на прямом краю, никогда в углу). Колонна принадлежит этому тайлу и попадает в игру вместе с ним. Тайлы уровня {n} принимают низкие, средние или высокие колонны; уровня {n} — средние или высокие; уровня {n} — высокие. (P)",
    "Place": "Разместить",
    "Place an object (a door, a lever, a chest…) and give it the trigger “{q}” to open the next room: the board is revealed little by little, as the players explore.": "Поставьте объект (дверь, рычаг, сундук…) и дайте ему триггер «{Q}», чтобы открыть следующую комнату: поле открывается понемногу, по мере того как игроки исследуют.",
    "Rooms": "Комнаты",
    "Rotate the selection or the piece in hand (R)": "Повернуть выделение или деталь в руке (R)",
    "Set the author in ⚙ Settings (it goes into the map file).": "Укажите автора в ⚙ Настройках (он попадает в файл карты).",
    "Settings: export folder, author, open, import, quick save/load": "Настройки: папка экспорта, автор, открытие, импорт, быстрое сохранение и загрузка",
    "Split your map into rooms.": "Разделите карту на комнаты.",
    "The Workshop: monsters, NPCs, items, tiles, objects, heroes and weapons of this map": "Мастерская: монстры, NPC, предметы, тайлы, объекты, герои и оружие этой карты",
    "Turn the map in three dimensions to see the layers ({n}). Looking only: go back to the plan to edit.": "Поворачивает карту в трёх измерениях, чтобы увидеть слои ({n}). Только для просмотра: для редактирования вернитесь к плану.",
    "View": "Вид",
    "Zoom in (+)": "Приблизить (+)",
