    "level {n} tall. (P)": "уровня {n} — высокие. (P)",
    "marks the squares where the heroes start, in the starting room ({n} to {n} squares). The players put their figures there before the first room appears.": "отмечает клетки, где начинают герои, в стартовой комнате (от {n} до {n} клеток). Игроки ставят туда свои фигурки до появления первой комнаты.",
    "same-level tiles cannot overlap. Underlays go under the tiles. (T)": "тайлы одного уровня не могут перекрываться. Подложки кладутся под тайлы. (T)",
    "to see the map in relief: elevated tiles, pillars, stairs and ladders.": "чтобы увидеть карту в рельефе: возвышенные тайлы, колонны, лестницы и приставные лестницы.",
    "wheel zooms": "колесо масштабирует",
