    "Balance: sets the tiers for {n}–{n}, {n} and {n} heroes by the game's points (room intensity ÷ {n} × heroes × {n} × progression, shared by the monsters placed in this room), each one above the other": "Баланс: задаёт ранги для {n}–{n}, {n} и {n} героев по игровым очкам (интенсивность комнаты ÷ {n} × герои × {n} × прогресс, делятся между монстрами, поставленными в эту комнату), каждый выше предыдущего",
    "Edit in the workshop": "Изменить в Мастерской",
    "Like the game's bosses (Levirax: tier {n}, {n} or {n} for {n}, {n} or {n} heroes). The difficulty (Journey, Heroic, Warfare) still applies on top.": "Как боссы игры (Левиракс: ранг {n}, {n} или {n} для {n}, {n} или {n} героев). Сложность (Приключение, Героический, Война) применяется сверху.",
