    "⚖ Balance": "⚖ Баланс",
    "Clear the map?": "Очистить карту?",
    "Clear without exporting": "Очистить без экспорта",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop, the other maps, the campaign and the author stay. Files already exported stay in the folder.": "Это сотрёт комнаты карты «{Q}» (их {n}): тайлы, колонны, объекты, монстров, клетки героев и их триггеры, а также её название и настройку карты (тексты, музыку, миссию, пулы, счётчики). Мастерская, другие карты, кампания и автор остаются. Уже экспортированные файлы остаются в папке.",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop and the author stay. Files already exported stay in the folder.": "Это сотрёт комнаты карты «{Q}» (их {n}): тайлы, колонны, объекты, монстров, клетки героев и их триггеры, а также её название и настройку карты (тексты, музыку, миссию, пулы, счётчики). Мастерская и автор остаются. Уже экспортированные файлы остаются в папке.",
    "The map has nothing to clear.": "На карте нечего очищать.",
    "Do you want to export it before clearing?": "Хотите экспортировать её перед очисткой?",
    "Everything not exported is lost.": "Всё неэкспортированное будет потеряно.",
    "Export, then clear": "Экспортировать и очистить",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers. The workshop, the map setup (name, texts, music, pools), the other maps and the campaign stay. Files already exported stay in the folder.": "Это сотрёт комнаты карты «{Q}» (их {n}): тайлы, колонны, объекты, монстров, клетки героев и их триггеры. Мастерская, настройка карты (название, тексты, музыка, пулы), другие карты и кампания остаются. Уже экспортированные файлы остаются в папке.",
    "Writes the .bcamp and its maps (download), then clears.": "Записывает .bcamp и его карты (скачивание), затем очищает.",
    "(a hero uses it: tap it with the hero chosen)": "(его использует герой: коснитесь его выбранным героем)",
    "(a player taps it with no hero chosen)": "(игрок касается его без выбранного героя)",
