    "Tapped with no hero, it only shows the text when looked at.": "При касании без героя показывает только текст при осмотре.",
    "Text when used": "Текст при использовании",
    "They run in order when a hero uses the object. A requirement goes inside the box of a trigger (open it) and holds back only that trigger.": "Срабатывают по порядку, когда герой использует объект. Требование ставится внутри окна триггера (откройте его) и блокирует только этот триггер.",
