    "Base level": "Базовый уровень",
    "The arrow shows the way up (R turns it). It climbs from the base level to the next one. From level {n} up it stands on tiles of its base level.": "Стрелка показывает направление подъёма (R поворачивает её). Лестница поднимается с базового уровня на следующий. Начиная с уровня {n} она стоит на тайлах своего базового уровня.",
