    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: short pillar, medium pillar, tall pillar.": "Пока нет: используйте инструмент «Колонна» на его гнёздах (уровень ${p.level} на панели). Здесь допустимы: низкая колонна, средняя колонна, высокая колонна.",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: tall pillar.": "Пока нет: используйте инструмент «Колонна» на его гнёздах (уровень ${p.level} на панели). Здесь допустима: высокая колонна.",
    "Pillars of this tile": "Колонны этого тайла",
