    "New rooms are born from an object: select it, add the trigger “{q}”. Pick a room here before touching what is in it.": "Новые комнаты рождаются из объекта: выберите его и добавьте триггер «{Q}». Выберите комнату здесь, прежде чем трогать то, что в ней.",
