    "W/S tilt": "W/S — наклон",
    "drag moves the map": "перетаскивание двигает карту",
    "right-drag or Alt+drag turns it": "перетаскивание правой кнопкой или Alt+перетаскивание поворачивает её",
    "world map: {n}, {n}": "карта мира: {n}, {n}",
