    "Everything on that tile goes with it.": "Всё, что на этом тайле, уходит вместе с ним.",
    "Takes one tile off the board with everything on it (objects, pillars, monsters). Frees it for reuse in a later room.": "Убирает с поля один тайл со всем, что на нём (объекты, колонны, монстры). Освобождает его для повторного использования в следующей комнате.",
    "Tile:": "Тайл:",
    "\"{q}\": remove enemy without a target": "«{Q}»: удаление врага без цели",
    "A spawn group…": "Группа появления…",
    "All monsters": "Все монстры",
    "Click it on the board": "Щёлкните его на поле",
    "If it is not on the board when the trigger fires, nothing happens.": "Если его нет на поле, когда срабатывает триггер, ничего не происходит.",
    "Monster:": "Монстр:",
    "Monsters of this room": "Монстры этой комнаты",
