    "Question": "Вопрос",
    "Then": "Затем",
    "each answer may show a text afterwards and have its own triggers.": "каждый ответ может затем показать текст и иметь свои триггеры.",
    "\"{q}\": objective without its object": "«{Q}»: задача без своего объекта",
    "A counter reaches a number": "Счётчик достигает числа",
    "An object is used (click it)": "Использован объект (щёлкните его)",
    "An objective does not end the map. To make it the mission, pick it in Map setup → Final mission → “{q}”.": "Задача не завершает карту. Чтобы сделать её миссией, выберите её в «Настройка карты» → «Последняя миссия» → «{Q}».",
    "Completed when": "Выполнено, когда",
    "Completed when it reaches": "Выполнено, когда достигает",
    "Declared at the table": "Объявляется за столом",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”)": "Объявляется за столом: приложение только показывает текст задачи среди задач и само ничего не проверяет. Она считается выполненной, когда стол отмечает её в панели Bigorna в игре (F{n} → «{Q}»)",
    "Declared at the table: the app only shows the objective text among the objectives and checks nothing by itself. It counts as completed when the table marks it in the Bigorna panel of the game (F{n} → “{q}”); only then the requirement “{q}” holds and, if it was chosen as the mission, the map ends.": "Объявляется за столом: приложение только показывает текст задачи среди задач и само ничего не проверяет. Она считается выполненной, когда стол отмечает её в панели Bigorna в игре (F{n} → «{Q}»); только тогда требование «{Q}» выполняется и, если она выбрана миссией, карта завершается.",
    "Give each object that counts (each key, each lever) an “{q}” trigger with this counter. The mission ends by itself when the number is reached.": "Дайте каждому засчитываемому объекту (каждому ключу, каждому рычагу) триггер «{Q}» с этим счётчиком. Миссия завершается сама, когда число достигнуто.",
    "Monsters are defeated": "Монстры побеждены",
    "Object:": "Объект:",
