    "The shop opens in its own window over the board; the next triggers run when it closes. To charge an entrance or limit who may enter, put a requirement on this trigger.": "Лавка открывается в собственном окне поверх поля; следующие триггеры срабатывают, когда она закрывается. Чтобы брать плату за вход или ограничить, кто может войти, поставьте требование на этот триггер.",
