    "“{q}” can now be used every time (change it in “{q}”); the trigger says how many times the armory opens.": "«{Q}» теперь можно использовать каждый раз (измените это в «{Q}»); триггер указывает, сколько раз открывается кузница.",
    "\"{q}\": shop without stock (pick where it comes from)": "«{Q}»: лавка без товара (выберите, откуда он берётся)",
    "\"{q}\": shop with an empty list": "«{Q}»: лавка с пустым списком",
    "\"{q}\": the shop sells an item that is not in the workshop": "«{Q}»: лавка продаёт предмет, которого нет в Мастерской",
    "\"{q}\": shop of the item pool, and the pool is empty (warning)": "«{Q}»: лавка из пула предметов, а пул пуст (предупреждение)",
    "\"{q}\": armory where nothing may change": "«{Q}»: кузница, где ничего нельзя менять",
    "Trigger <b>Shop / Armory</b>: the party visits a shop or an armory in the middle of the map, as in the city, then goes on: a merchant in the camp, a smith at the outpost.": "Триггер <b>Лавка / Кузница</b>: отряд посещает лавку или кузницу посреди карты, как в городе, затем идёт дальше: торговец в лагере, кузнец на заставе.",
    "Give": "Дать",
    "Random crafting materials": "Случайные материалы для создания",
    "Units drawn at random from the materials the party carries (never below zero).": "Единицы, выбранные случайно из материалов, которые есть у отряда (никогда ниже нуля).",
    "The party has gold": "У отряда есть золото",
    "The party must have at least this much gold (a merchant’s price).": "У отряда должно быть хотя бы столько золота (цена торговца).",
