    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "У каждого оружия в игре один герой (за ним следуют его детали, лавка, инвентарь и достижения). Если выбрать оружие другого героя, ему взамен отдаётся это. Числа берутся из оружия: они меняются на вкладке «Оружие». Оружие принадлежит профилю: оно остаётся с ним, если герой уходит.",
