    "Drag the pieces to put the weapon together as you want it; the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "Перетаскивайте детали, чтобы собрать оружие так, как вам нужно; колесо (или ползунок) меняет размер выбранной детали, Shift+колесо, Q/E или ползунок поворота поворачивают её, стрелки сдвигают. Деталь видна только внутри своей рамки: то, что выходит за неё, обрезается (показано бледно).",
