    "Potions and one-use cards the heroes spend during a quest. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "Зелья и одноразовые карты, которые герои тратят во время сценария. Выдавать триггерами, наградами и диалогами, ронять с монстров и создавать можно только предметы из списка Мастерской.",
