    "Box {n}": "Окно {n}",
    "Boxes of text, questions and videos (your own films), played in a row (it goes after the selected card)": "Окна текста, вопросов и видео (ваших собственных фильмов), проигрываемые подряд (встаёт после выбранной карточки)",
    "Boxes of “{q}”: drag from a box’s ● (or an answer’s ●) onto another box to say what comes next": "Окна «{Q}»: тяните от ● окна (или ● ответа) к другому окну, чтобы указать, что будет дальше",
    "Boxes play in the order of the arrows, starting at the first. A question box branches: each answer leads to its own next box. A video box plays your own film (MP{n} or WebM) between the other boxes.": "Окна проигрываются в порядке стрелок, начиная с первого. Окно-вопрос ветвится: каждый ответ ведёт к своему следующему окну. Окно видео проигрывает ваш собственный фильм (MP{n} или WebM) между другими окнами.",
    "Build the rooms of this map": "Построить комнаты этой карты",
    "Build the rooms of this side quest": "Построить комнаты этого побочного сценария",
    "Build the rooms ▸": "Построить комнаты ▸",
