    "the bell hangs in its frame: a bell on the table takes the bell frame, and with one frame only one bell hangs at a time": "колокол висит в своей раме: колокол на столе занимает раму колокола, и при одной раме одновременно висит только один колокол",
    "Del deletes": "Del удаляет",
