    "Drag a card to move it": "Перетащите карточку, чтобы переместить её",
    "Drag a marker to place it on the world map": "Перетащите метку, чтобы разместить её на карте мира",
    "Erase the campaign, all its maps and its workshop from the editor": "Стереть из редактора кампанию, все её карты и её Мастерскую",
    "Every map, side quest and waypoint has a place here and a marker kind: main quest, side quest, narrative event or city visit.": "У каждой карты, побочного сценария и точки маршрута здесь есть место и вид метки: основной сценарий, побочный сценарий, повествовательное событие или посещение города.",
    "Everything of this campaign is erased from the editor, and it cannot be undone:": "Всё, что относится к этой кампании, стирается из редактора, и это нельзя отменить:",
    "Export campaign": "Экспорт кампании",
    "Export, then delete": "Экспортировать и удалить",
    "Files already exported stay in the folder": "Уже экспортированные файлы остаются в папке",
    "Files already exported stay in the folder; delete them there if you want. Autosave stops following this campaign, so it will not erase them. The game keeps the progress of any party that played it.": "Уже экспортированные файлы остаются в папке; удалите их там, если хотите. Автосохранение перестаёт следить за этой кампанией, так что оно их не сотрёт. Игра сохраняет прогресс каждого отряда, который в неё играл.",
    "Fit the whole flow in the view": "Вписать весь ход сюжета в экран",
    "Give crafting materials": "Дать материалы для создания",
    "Give the campaign a name (campaign screen).": "Дайте кампании название (экран кампании).",
    "Happens as": "Происходит как",
    "It waits for the next visit to the city after the card before it": "Ждёт следующего посещения города после карточки перед ней",
    "Lay the cards out left to right": "Расставить карточки слева направо",
    "Leads to": "Ведёт к",
    "Leave anyway": "Всё равно уйти",
    "Main quest": "Основной сценарий",
    "Map picture": "Картинка карты",
    "Mark a map or waypoint as completed": "Отметить карту или точку маршрута выполненной",
    "Name of the campaign": "Название кампании",
    "Narrative event": "Повествовательное событие",
    "Narrative event (a marker on the world map)": "Повествовательное событие (метка на карте мира)",
    "Narrative event (plays at its point of the story)": "Повествовательное событие (проигрывается в своей точке истории)",
    "New variable (Spared the bandit, Sided with the rebels…)": "Новая переменная (Пощадили бандита, Встали на сторону повстанцев…)",
    "No remembered choice yet: in a question box, tick “{q}”.": "Запомненных выборов пока нет: в окне-вопросе отметьте «{Q}».",
    "On the world map as": "На карте мира как",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows": "PNG или JPG, {n}:{n} ({n}×{n} подходит точно). Покрывает всю рамку, которую показывает игра",
    "PNG or JPG, {n}:{n} ({n}×{n} fits exactly). It covers the whole frame the game shows; the game's water, burnt land, place names and roads are hidden. The mist covers a fixed region of the game's own map (the Mistlands).": "PNG или JPG, {n}:{n} ({n}×{n} подходит точно). Покрывает всю рамку, которую показывает игра; вода, выжженная земля, названия мест и дороги игры скрываются. Туман покрывает фиксированную область собственной карты игры (Туманные земли).",
    "Place this waypoint on the world map": "Разместить эту точку маршрута на карте мира",
    "Plays as": "Проигрывается как",
    "Point at a line to light its arrow. To see where a card leads, click its ●.": "Наведите на линию, чтобы подсветить её стрелку. Чтобы увидеть, куда ведёт карточка, щёлкните её ●.",
    "Remember a choice": "Запомнить выбор",
