    "Remove this arrow": "Убрать эту стрелку",
    "Rename: every answer, card and map trigger that uses it follows": "Переименовать: новое имя получат все ответы, карточки и триггеры карт, которые её используют",
    "Rewards on completion": "Награды за выполнение",
