    "Set by": "Чем задаётся",
    "Side quest": "Побочный сценарий",
    "Side quest {n}": "Побочный сценарий {n}",
    "Simulation": "Симуляция",
    "Stay and fill them": "Остаться и заполнить их",
    "Story flow": "Ход сюжета",
    "The choices the campaign remembers from one map to the next: spared the bandit, sided with the rebels, took the cursed ring… A choice is set when the party picks an answer ticked “{q}” (or by a “{q}” action) and stays for the rest of the campaign. Cards of the story flow and triggers of the maps can then happen only if the party made it, or did not.": "Выборы, которые кампания запоминает от карты к карте: пощадили бандита, встали на сторону повстанцев, взяли проклятое кольцо… Выбор задаётся, когда отряд выбирает ответ с отметкой «{Q}» (или действием «{Q}»), и сохраняется до конца кампании. Карточки хода сюжета и триггеры карт могут затем происходить, только если отряд сделал этот выбор или не сделал.",
    "The party moves on the world map (it goes after the selected card)": "Отряд перемещается по карте мира (встаёт после выбранной карточки)",
    "The scene goes on with the next box when the film ends.": "Когда фильм заканчивается, сцена продолжается следующим окном.",
    "Then:": "Затем:",
    "They are exported as they are. Fill them, or delete the ones you do not need.": "Они экспортируются как есть. Заполните их или удалите ненужные.",
    "Type the name of the campaign to confirm:": "Введите название кампании для подтверждения:",
    "Unlock a map or waypoint": "Открыть карту или точку маршрута",
    "Use my own city picture…": "Использовать свою картинку города…",
    "Use my own world map…": "Использовать свою карту мира…",
    "Used by": "Где используется",
