    "Video {n}": "Видео {n}",
    "Waypoint {n}": "Точка маршрута {n}",
    "What it means (a note for you)": "Что это значит (заметка для вас)",
    "When this box is shown": "Когда показывается это окно",
    "World map": "Карта мира",
    "World map position: -{n}, {n}.": "Положение на карте мира: -{n}, {n}.",
