    "Writes the .bcamp and its maps (download), then deletes.": "Записывает .bcamp и его карты (скачивание), затем удаляет.",
    "You are building the rooms of this map. Pick another map, or add maps, waypoints and dialogues, on the campaign screen (“{q}” above).": "Вы строите комнаты этой карты. Выберите другую карту или добавьте карты, точки маршрута и диалоги на экране кампании («{Q}» выше).",
    "after Map {n}": "после «Карта {n}»",
    "after Side quest {n}": "после «Побочный сценарий {n}»",
    "after Waypoint {n}": "после «Точка маршрута {n}»",
    "after a waypoint it plays on arrival": "после точки маршрута проигрывается по прибытии",
    "arrows nudge the selected card (or the view)": "стрелки сдвигают выбранную карточку (или вид)",
    "before anything it opens the campaign.": "перед всем остальным открывает кампанию.",
    "campaign progression {n} (Map setup → Balancing).": "прогресс кампании {n} («Настройка карты» → «Баланс»).",
    "double-click the background adds a box": "двойной щелчок по фону добавляет окно",
    "drag from its ● onto another card to link (the target comes after)": "тяните от её ● к другой карточке, чтобы связать (цель идёт после)",
    "end of the scene": "конец сцены",
    "faded dots are the official destinations": "бледные точки — официальные пункты назначения",
    "from the start": "с самого начала",
    "map {n} of {n}": "карта {n} из {n}",
    "narrator": "рассказчик",
    "nothing depends on it yet: pick it in “{q}” of a card, or as the requirement “{q}” of a map trigger.": "от неё пока ничего не зависит: выберите её в «{Q}» карточки или как требование «{Q}» триггера карты.",
    "nothing sets it yet: tick “{q}” in a question box and give it this name. Until then “{q}” is never true.": "её пока ничто не задаёт: отметьте «{Q}» в окне-вопросе и дайте ей это имя. До тех пор «{Q}» никогда не истинно.",
    "only a question may branch": "ветвиться может только вопрос",
    "progression {n}": "прогресс {n}",
    "question": "вопрос",
    "the name is yours.": "название выбираете вы.",
    "the scenes that follow it play in the same visit.": "сцены, следующие за ней, проигрываются в то же посещение.",
    "the story flow: {n} card(s), {n} scene(s) with their boxes, {n} story variable(s)": "ход сюжета — карточек: {n}, сцен с их окнами: {n}, сюжетных переменных: {n}",
    "the workshop: {n} monster(s), {n} NPC(s), {n} item(s), {n} hero(es), {n} weapon(s), {n} recipe(s), {n} feat(s), {n} tile(s)/object(s) of your own": "Мастерская — монстров: {n}, NPC: {n}, предметов: {n}, героев: {n}, оружия: {n}, рецептов: {n}, достижений: {n}, ваших тайлов/объектов: {n}",
    "the world map positions, the rewards, the music and videos chosen": "положения на карте мира, награды, выбранные музыка и видео",
    "with your own map picture, draw the roads on the left": "со своей картинкой карты рисуйте дороги слева",
    "without a name": "без названия",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene": "Окон: {n}. Текст, вопросы и видео (ваши собственные фильмы), проигрываемые одно за другим в той же рамке. Проигрывается в этой точке истории: после карты это заключительная сцена карты",
    "{n} box(es): text, questions and videos (your own films), played one after the other in the same frame. Played at this point of the story: after a map it is the map’s closing scene; after a waypoint it plays on arrival; before anything it opens the campaign.": "Окон: {n}. Текст, вопросы и видео (ваши собственные фильмы), проигрываемые одно за другим в той же рамке. Проигрывается в этой точке истории: после карты это заключительная сцена карты; после точки маршрута проигрывается по прибытии; перед всем остальным открывает кампанию.",
    "{n} room(s)": "Комнат: {n}",
