    "✦ Generate room": "✦ Создать комнату",
    "Build a room from an archetype: three candidates to pick from": "Построить комнату по архетипу: три кандидата на выбор",
    "✦ Generate map": "✦ Создать карту",
    "✦ Generate map (experimental)": "✦ Создать карту (экспериментально)",
