    "Original maps": "Оригинальные карты",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "Оригинальные карты игры мод Bigorna читает из вашей собственной копии игры: запустите игру один раз с установленным модом (титульный экран их подготовит), затем снова откройте редактор из папки Editor игры.",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "Сценарии игры, превращённые в карты редактора: тайлы, объекты, комнаты, монстры и логика, которую могут выразить триггеры.",
    "Each map comes with notes on what was simplified (Map setup).": "К каждой карте прилагаются заметки о том, что было упрощено («Настройка карты»).",
