    "Variations of the picked one: keep its": "Вариации выбранного: сохранить его",
    "Pick a candidate first.": "Сначала выберите кандидата.",
    "The Workshop holds too little to generate with variety": "В Мастерской слишком мало всего для разнообразной генерации",
    "Monsters to draw": "Монстры для жребия",
    "Monster types": "Типы монстров",
    "Item cards": "Карты предметов",
    "The generators use only what is in the Workshop: its monsters, items, materials and objects, within the chosen boxes.": "Генераторы используют только то, что есть в Мастерской: её монстров, предметы, материалы и объекты, в пределах выбранных коробок.",
    "Trim it in the Workshop as you like.": "Урежьте его в Мастерской, как хотите.",
    "Add a starter selection": "Добавить стартовый набор",
    "Crypt": "Склеп",
    "Village": "Деревня",
    "Cave": "Пещера",
    "Complications": "Осложнения",
