    "An original of the game: it stays as the game has it.": "Оригинал игры: остаётся таким, как в игре.",
    "Change it here: changed, it becomes yours, with the same id (what uses it gets your version; the package’s file stays as it is). To take it out, remove the package (📚 My packages).": "Изменяйте здесь: после изменения запись становится вашей, с тем же id (то, что её использует, получает вашу версию; файл пакета остаётся как есть). Чтобы убрать её, удалите пакет (📚 Мои пакеты).",
    "It replaces the map on screen, fully editable.": "Она заменяет карту на экране и полностью редактируется.",
    "A whole map: why the heroes go in (premise), what they must do to win (objective), what changes along the way (extra rule), how the tension grows and the end. It replaces the map on screen, fully editable.": "Целая карта: зачем герои идут туда (предпосылка), что они должны сделать, чтобы победить (задача), что меняется по ходу (доп. правило), как растёт напряжение и финал. Она заменяет карту на экране и полностью редактируется.",
    "Add to the campaign": "Добавить в кампанию",
