    "A raised platform over the floor: whoever holds the height sees everything.": "Приподнятая платформа над полом: кто держит высоту, тот видит всё.",
    "Moving: drag the room · R turns it · Esc or a click outside ends it": "Перемещение: тяните комнату · R поворачивает её · Esc или щелчок снаружи завершает",
