    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "Это сотрёт всё, что хранит редактор: карту или кампанию на экране, Мастерскую (монстров, предметы, материалы, объекты, импортированные или сделанные), пакеты (в приложении: папку Pacotes и каждый пакет в ней), картинки, хранимые редактором, быстрое сохранение, ваши архетипы, подсказки и предупреждения, положения и размеры окон, автора, папку экспорта и автосохранение.",
